UPDATE public.approvals SET params_json = '{"account_id":"conta-1","caption":"\ud83d\ude80 Quer come\u00e7ar a programar mas n\u00e3o sabe por onde come\u00e7ar? Nossa aula de Python para iniciantes foi feita exatamente para voc\u00ea! Em apenas algumas sess\u00f5es, voc\u00ea vai aprender a instalar o Python, escrever seu primeiro c\u00f3digo, entender vari\u00e1veis, tipos de dados, operadores e estruturas de controle como if, while e for. Tudo isso com exemplos pr\u00e1ticos que voc\u00ea pode testar em tempo real. N\u00e3o importa se voc\u00ea nunca programou antes \u2013 n\u00f3s explicamos tudo de forma simples e passo a passo. Ao final da aula, voc\u00ea j\u00e1 ter\u00e1 a base para criar seus pr\u00f3prios scripts, automatizar tarefas e at\u00e9 come\u00e7ar a explorar \u00e1reas como ci\u00eancia de dados, desenvolvimento web e intelig\u00eancia artificial. \ud83d\udcda\ud83d\udcbb\n\nO que voc\u00ea vai aprender:\n1\ufe0f\u20e3 Instala\u00e7\u00e3o e configura\u00e7\u00e3o do ambiente Python\n2\ufe0f\u20e3 Sintaxe b\u00e1sica e boas pr\u00e1ticas\n3\ufe0f\u20e3 Vari\u00e1veis, tipos de dados e operadores\n4\ufe0f\u20e3 Estruturas de controle (if, while, for)\n5\ufe0f\u20e3 Fun\u00e7\u00f5es simples e reutiliza\u00e7\u00e3o de c\u00f3digo\n6\ufe0f\u20e3 Pequenos projetos pr\u00e1ticos para fixar o aprendizado\n\nN\u00e3o perca a chance de dar o primeiro passo na sua jornada de programa\u00e7\u00e3o. Inscreva-se agora e transforme sua curiosidade em habilidade! #Python #Iniciantes #Programa\u00e7\u00e3o #AprenderPython #C\u00f3digo #Desenvolvimento #Tecnologia #Estudo #Educa\u00e7\u00e3o #Dicas","content_hash":"163310ae5064f876a779f001b5a3324ee96b2324f13ff98fa939a20dd3ca91fb","media_hash":"6363761bf02aa99609e399211eb15ce19fedf93ca5fed4232f92f0859ce508e7","persona_id":"ativa","platform":"tiktok","scheduled_for":null}', result_json = NULL WHERE id = 3;

CREATE OR REPLACE FUNCTION public.ctl_append_audit_exact(p_ts numeric, p_run_id text, p_actor text, p_event text, p_action text, p_status text, p_detail text, p_canon text)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE prev text; h text; new_id bigint;
BEGIN
  PERFORM public.require_operator();
  PERFORM pg_advisory_xact_lock(hashtext('audit_chain'));
  SELECT hash INTO prev FROM public.audit_events ORDER BY id DESC LIMIT 1;
  prev := coalesce(prev, repeat('0', 64));
  h := encode(sha256(convert_to(prev || p_canon, 'UTF8')), 'hex');
  INSERT INTO public.audit_events (ts, ts_exact, run_id, actor, event, action, status, detail, prev_hash, hash)
  VALUES (p_ts::double precision, p_ts, p_run_id, p_actor, p_event, p_action, p_status, p_detail, prev, h) RETURNING id INTO new_id;
  RETURN new_id;
END $$;
REVOKE EXECUTE ON FUNCTION public.ctl_append_audit_exact(numeric, text, text, text, text, text, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.ctl_append_audit_exact(numeric, text, text, text, text, text, text, text) TO authenticated;
COMMENT ON FUNCTION public.ctl_append_audit(double precision, text, text, text, text, text, text, text) IS 'DEPRECATED: replaced by ctl_append_audit_exact';